-- Live call scripts (DEV). Generated from src/features/live-call/data/scripts.js:
-- William Davis (CHF discharge, confused about the torsemide dose) and
-- Annette Brave (ED chest pain, ACS ruled out, asking about labs), the two
-- patients on a live agent call in the TOC IP worklist.
-- Run after live_call_scripts_migration.sql and
-- live_call_scripts_summary_migration.sql. Re-running updates the rows.

INSERT INTO public.live_call_scripts (member_id, reason, interpreter, summary, speakers, lines, points, meds, items) VALUES
  ('11143', 'TCM interactive contact after CHF discharge (St. Mary Hospital, 11/08). Taken over from Erica: confused about the new torsemide dose.', 'English', 'TCM interactive contact by phone after CHF discharge (St. Mary Hospital, 11/08), taken over from Erica. He had been taking one torsemide 20 mg each morning instead of two. Reconciled with teach-back: torsemide 40 mg (two tablets) every morning, furosemide stopped, metoprolol succinate up to 50 mg nightly. Weight 186 lb, up 4 lb since discharge, with mild ankle swelling and no change in orthopnea; Dr. Chen to be notified today. Reviewed daily weights and when to call: 3 lb in a day, 5 lb in a week, or worse breathing. 11 torsemide tablets left; refill requested. Large-print pill organizer for poor vision. 7-day TCM visit Fri 11/13 at 10:20 AM, daughter driving. His goal: walk to church on Sundays again.', '{"cm":{"role":"Care Manager"},"pt":{"name":"William Davis","role":"Patient","ini":"WD"}}'::jsonb, '[{"who":"cm","t":"00:03","text":"Hi Mr. Davis, this is {cmFirst}, the nurse care manager working with Erica, who called you earlier."},{"who":"pt","t":"00:11","text":"Yes, thank you for calling back. I’m mixed up about my water pills."},{"who":"cm","t":"00:19","text":"Let’s sort that out together. Can you read me the labels on the bottles you have?"},{"who":"pt","t":"00:31","text":"One says furosemide 40. That’s the one I’ve had for years.","hl":"furosemide 40","item":"w1"},{"who":"pt","t":"00:40","text":"The new one from St. Mary is torsemide 20. I’ve been taking one each morning.","hl":"taking one each morning","item":"w2"},{"who":"cm","t":"00:52","text":"The discharge orders say two torsemide tablets, 40 milligrams, every morning, and no more furosemide."},{"who":"pt","t":"01:04","text":"Two torsemide, no furosemide. Got it. The print on these labels is so small though.","hl":"print on these labels is so small","item":"w3"},{"who":"cm","t":"01:16","text":"I’ll get you a large-print pill organizer. How many torsemide tablets do you have left?","hl":"large-print pill organizer","item":"w8"},{"who":"pt","t":"01:25","text":"Eleven left. They gave me fourteen.","hl":"Eleven left","item":"w4"},{"who":"cm","t":"01:36","text":"I’ll ask Dr. Chen to send a refill today. What did your scale say this morning?"},{"who":"pt","t":"01:44","text":"186 pounds. I was 182 when I left the hospital.","hl":"186 pounds","item":"w9"},{"who":"cm","t":"01:53","text":"That’s up 4 pounds since Sunday, so I’m letting Dr. Chen know today. Any more swelling, or trouble breathing lying down?"},{"who":"pt","t":"02:05","text":"My ankles are a little puffy. I sleep on two pillows, same as always."},{"who":"cm","t":"02:14","text":"Weigh every morning, and call us if you gain 3 pounds in a day or 5 in a week, or if your breathing gets worse."},{"who":"pt","t":"02:26","text":"Three in a day or five in a week. I’ll write it on the fridge."},{"who":"cm","t":"02:34","text":"You need a visit with Dr. Chen within 7 days of discharge. I have Friday at 10:20 AM."},{"who":"pt","t":"02:43","text":"Friday works. My daughter can drive me.","hl":"Friday works","item":"w5"},{"who":"pt","t":"02:51","text":"And the metoprolol, they said 50 at night now?","hl":"metoprolol, they said 50","item":"w6"},{"who":"cm","t":"03:00","text":"Yes, metoprolol succinate 50 at night. I’ll put everything on one list for you."},{"who":"pt","t":"03:09","text":"I’d like to get back to walking to church on Sundays.","hl":"walking to church on Sundays","item":"w7"}]'::jsonb, '[{"t":"Which diuretic he takes (teach-back)","line":6},{"t":"Supply of new medications","line":8},{"t":"Weight and swelling since discharge","line":12},{"t":"Red flags to call about","line":14},{"t":"7-day visit with Dr. Chen","line":16},{"t":"Dose changes from discharge","line":18}]'::jsonb, '[{"n":"Furosemide 40 mg","sig":"Daily","st":"Stopped at discharge","tone":"danger","status":"Stopped","start":"2019-04-10","stop":"2026-11-08","reason":"Therapeutic Change","by":"Dr. L. Chen"},{"n":"Torsemide 20 mg","sig":"2 tablets (40 mg) every morning","st":"11 tablets left","tone":"danger","start":"2026-11-08","last":"2026-11-08","days":7,"by":"St. Mary Hospital discharge orders"},{"n":"Metoprolol succinate 25 mg","sig":"Nightly","st":"Changed at discharge","tone":"warning","start":"2024-02-01","last":"2026-10-20","days":30,"by":"Dr. L. Chen"},{"n":"Lisinopril 10 mg","sig":"Daily","st":"No change","tone":"neutral","start":"2022-06-12","last":"2026-10-15","days":90,"by":"Dr. L. Chen"}]'::jsonb, '[{"id":"w1","type":"Dose Change","tone":"danger","icon":"solar:pill-linear","where":"Medications","title":"Stop furosemide 40 mg (replaced by torsemide)","src":["Reconciled","Discharge orders, St. Mary Hospital 11/08"],"fields":[["Teach-back","Patient repeated: torsemide only"],["Disposal","Pharmacy take-back"]]},{"id":"w2","type":"Dose Change","tone":"warning","icon":"solar:pill-linear","where":"Medications","title":"Torsemide 40 mg (two 20 mg tablets) every morning","src":["Reconciled","Discharge orders, St. Mary Hospital 11/08"],"fields":[["Was Taking","One tablet (20 mg) since discharge"],["Teach-back","Two tablets every morning"]]},{"id":"w3","type":"New Barrier","tone":"warning","icon":"solar:flag-linear","where":"Care Plan","title":"Poor vision limits reading medication labels","fields":[["Linked Goal","Safe medication use after discharge"],["Suggested Intervention","Large-print pill organizer"]]},{"id":"w8","type":"New Task","tone":"neutral","icon":"solar:checklist-minimalistic-linear","where":"Tasks","title":"Deliver large-print pill organizer","fields":[["Assignee","{cm}"],["Due","11/12/2026"]]},{"id":"w4","type":"Medication Refill","tone":"info","icon":"solar:pill-linear","where":"Medications","title":"Refill torsemide 20 mg, 2 tablets daily, 30 days","src":["Refill Request","Routes to Dr. L. Chen to sign"],"fields":[["Supply Left","11 tablets (5 days at 2 a day)"],["Signs","Dr. L. Chen"]]},{"id":"w9","type":"New Task","tone":"danger","icon":"solar:danger-triangle-linear","where":"Tasks","title":"Notify Dr. L. Chen: weight up 4 lb in 3 days","fields":[["Reading","186 lb today, 182 lb at discharge 11/08"],["Symptoms","Mild ankle swelling, no orthopnea change"],["Context","Took half the torsemide dose since discharge"],["Assignee","{cm}"],["Due","Today"]]},{"id":"w5","type":"New Appointment","tone":"primary","icon":"solar:calendar-add-linear","where":"Calendar","title":"TCM 7-day visit with Dr. L. Chen","fields":[["When","Fri, 11/13/2026 · 10:20 AM"],["Transport","Daughter driving"],["Counts For","TCM face-to-face within 7 days (99496)"]]},{"id":"w6","type":"Dose Change","tone":"warning","icon":"solar:pill-linear","where":"Medications","title":"Metoprolol succinate 25 mg → 50 mg nightly","src":["Reconciled","Discharge orders, St. Mary Hospital 11/08"],"fields":[["Teach-back","Confirmed 50 mg at night"]]},{"id":"w7","type":"New Goal","tone":"primary","icon":"solar:target-linear","where":"Care Plan","title":"Walk to church on Sundays again","fields":[["In His Words","“I’d like to get back to walking to church on Sundays.”"],["Target","Walk 10 minutes daily by week 4"],["Program","TOC IP, then CCM"]]}]'::jsonb),
  ('11089', 'ED follow-up after chest pain, rule out ACS (City Medical ER, 11/10). Taken over from Erica: asking about follow-up labs.', 'English', 'ED follow-up call after chest pain with ACS ruled out (City Medical ER, 11/10), taken over from Erica. Troponins were normal and she has had no chest pain since Tuesday night. Fasting lipid panel at Quest Fri 11/13 at 7:30 AM. 7-day ED follow-up with Dr. Patel Mon 11/16 at 2:00 PM. Taking aspirin 81 mg every morning as started in the ER. She was unsure when to use nitroglycerin; taught back: sit down, one tablet under the tongue, call 911 if the pain lasts 5 minutes. Stress test order to be requested from Dr. Patel before Monday.', '{"cm":{"role":"Care Manager"},"pt":{"name":"Annette Brave","role":"Patient","ini":"AB"}}'::jsonb, '[{"who":"cm","t":"00:03","text":"Hi Annette, this is {cmFirst}, a nurse care manager. Erica mentioned you had questions about your labs."},{"who":"pt","t":"00:11","text":"Yes. The ER said my heart tests were fine, but I need more labs?"},{"who":"cm","t":"00:20","text":"Your troponin tests were normal, which is reassuring. Has the chest pain come back at all?"},{"who":"pt","t":"00:31","text":"No, not since Tuesday night. I feel okay."},{"who":"cm","t":"00:39","text":"Good. The ER asked for a fasting cholesterol panel, and a stress test with your doctor."},{"who":"pt","t":"00:51","text":"Can I do the blood work this week? Mornings are easier before work.","hl":"Mornings are easier before work","item":"a1"},{"who":"cm","t":"01:02","text":"I can book Quest on Friday at 7:30 AM. Nothing to eat after midnight, water is fine."},{"who":"pt","t":"01:12","text":"Friday at 7:30 works."},{"who":"cm","t":"01:19","text":"You also need a visit with Dr. Patel within 7 days of the ER visit. Monday at 2:00 PM is open."},{"who":"pt","t":"01:29","text":"Monday at 2 is fine.","hl":"Monday at 2 is fine","item":"a2"},{"who":"cm","t":"01:37","text":"The ER started a baby aspirin. Are you taking it?"},{"who":"pt","t":"01:44","text":"One 81 milligram every morning, like they said.","hl":"One 81 milligram every morning","item":"a3"},{"who":"pt","t":"01:53","text":"They gave me nitroglycerin tablets too, but I’m scared to use them.","hl":"scared to use them","item":"a4"},{"who":"cm","t":"02:04","text":"If the pain comes back, sit down and put one under your tongue. If it isn’t gone in 5 minutes, call 911."},{"who":"pt","t":"02:16","text":"Sit down, one under the tongue, and 911 if it lasts 5 minutes."},{"who":"cm","t":"02:24","text":"That’s exactly right. I’ll ask Dr. Patel to order the stress test before Monday’s visit.","hl":"order the stress test","item":"a5"}]'::jsonb, '[{"t":"ER results and symptoms since","line":3},{"t":"Fasting labs this week","line":7},{"t":"7-day follow-up with Dr. Patel","line":9},{"t":"New medications from the ER","line":12},{"t":"Chest pain plan (teach-back)","line":14}]'::jsonb, '[{"n":"Aspirin 81 mg","sig":"Every morning","st":"Started in ER","tone":"primary","start":"2026-11-10","by":"City Medical ER (over the counter)"},{"n":"Nitroglycerin 0.4 mg SL","sig":"1 tablet as needed for chest pain","st":"Started in ER","tone":"primary","start":"2026-11-10","last":"2026-11-10","by":"City Medical ER"},{"n":"Lisinopril 20 mg","sig":"Daily","st":"No change","tone":"neutral","start":"2021-03-15","last":"2026-10-05","days":90,"by":"Dr. A. Patel"},{"n":"Metformin 1000 mg","sig":"Twice daily with meals","st":"No change","tone":"neutral","start":"2020-08-01","last":"2026-10-20","days":30,"by":"Dr. A. Patel"}]'::jsonb, '[{"id":"a1","type":"New Appointment","tone":"primary","icon":"solar:calendar-add-linear","where":"Calendar","title":"Fasting lipid panel","fields":[["When","Fri, 11/13/2026 · 7:30 AM"],["Where","Quest Diagnostics"],["Prep","Fasting from midnight, water is fine"]]},{"id":"a2","type":"New Appointment","tone":"primary","icon":"solar:calendar-add-linear","where":"Calendar","title":"ED follow-up visit with Dr. A. Patel","fields":[["When","Mon, 11/16/2026 · 2:00 PM"],["Counts For","7-day follow-up after the ED visit"]]},{"id":"a3","type":"New Medication","tone":"success","icon":"solar:pill-linear","where":"Medications","title":"Aspirin 81 mg every morning","src":["Reconciled","ER discharge orders, City Medical 11/10"],"fields":[["Confirmed","Taking daily since discharge"]]},{"id":"a4","type":"New Barrier","tone":"warning","icon":"solar:flag-linear","where":"Care Plan","title":"Unsure when to use nitroglycerin","fields":[["Linked Goal","Know what to do if chest pain returns"],["Teach-back","Sit, 1 tablet under the tongue, 911 if not gone in 5 minutes"]]},{"id":"a5","type":"New Task","tone":"neutral","icon":"solar:checklist-minimalistic-linear","where":"Tasks","title":"Request outpatient stress test order from Dr. A. Patel","fields":[["Assignee","{cm}"],["Due","11/12/2026"],["Before","ED follow-up on 11/16"]]}]'::jsonb)
